export const GROUP_DECISIONS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu keputusan bersama",q:"'Keputusan bersama' dalam tim adalah keputusan yang...",options:["Diambil setelah mendengar & mempertimbangkan pendapat anggota, lewat cara yang disepakati","Diambil oleh satu orang yang berwenang lalu diberitahukan kepada anggota tanpa kesempatan menanggapi","Tak diambil secara jelas, tetapi dianggap ada; anggota tidak menyatakan keberatan"],answer:0,explain:"Keputusan bersama bukan berarti semua harus setuju bulat, tapi semua didengar & prosesnya adil.",hint:"Dengar semua + cara disepakati, atau satu orang memutuskan?"},
{n:2,type:"mcq",micro:"Kenapa melibatkan tim",q:"Keuntungan mengambil keputusan penting bersama tim:",options:["Menghindari tanggung jawab; keputusan dibuat ramai-ramai dan kesalahan bisa dibagi ke banyak anggota","Lebih banyak informasi & sudut pandang dipertimbangkan, & anggota lebih mendukung keputusan yang ikut mereka buat","Lebih cepat dibanding keputusan sendiri; semua anggota langsung setuju tanpa perlu berdiskusi"],answer:1,explain:"Keputusan yang dibuat bersama biasanya lebih matang & dijalankan lebih sepenuh hati.",hint:"Lebih matang + lebih didukung, atau selalu lebih cepat?"},
{n:3,type:"mcq",micro:"Kapan tidak perlu keputusan bersama",q:"Keputusan yang WAJAR diambil satu orang (koordinator) tanpa rapat panjang:",options:["Semua keputusan, besar maupun kecil, boleh diambil sendiri koordinator tanpa bertanya pada anggota","Tidak ada; semua keputusan wajib dibahas di rapat lengkap, termasuk yang harus dijawab dalam menit","Hal kecil, rutin, atau mendesak yang tidak bisa menunggu — asalkan dijelaskan ke tim setelahnya"],answer:2,explain:"Merapatkan setiap hal kecil membuang waktu. Bedakan keputusan besar (bersama) & kecil/mendesak (koordinator, lalu jelaskan).",hint:"Hal kecil/mendesak (lalu jelaskan), atau semua wajib rapat?"},
{n:4,type:"mcq",micro:"Cara memutuskan: konsensus",q:"'Konsensus' berarti tim...",options:["Berdiskusi sampai menemukan pilihan yang semua bisa terima/dukung, meski bukan pilihan pertama tiap orang","Semua anggota harus menjadikan keputusan itu pilihan pertamanya, kalau tidak, keputusan belum dianggap sah","Voting cepat tanpa diskusi, lalu pilihan dengan suara terbanyak langsung dijalankan sebelum alasan didengar"],answer:0,explain:"Konsensus bukan 'semua senang', tapi 'semua bisa hidup dengan ini & mendukungnya'. Butuh waktu tapi kuat.",hint:"Semua bisa terima & dukung, atau semua harus suka?"},
{n:5,type:"mcq",micro:"Cara memutuskan: voting",q:"Voting (suara terbanyak) cocok dipakai ketika...",options:["Tanpa mendengar pendapat atau alasan siapa saja lebih dulu; suara terbanyak sudah dianggap cukup menentukan pilihan terbaik","Pilihan sudah jelas, waktu terbatas, & tim sepakat memakai cara ini — dengan tetap mendengar alasan tiap pihak dulu","Untuk semua keputusan tanpa kecuali, kecil maupun penting; voting dianggap cara yang paling adil bagi tim"],answer:1,explain:"Voting cepat & jelas, tapi bisa membuat minoritas merasa kalah. Dengar dulu, baru voting.",hint:"Pilihan jelas + waktu terbatas + dengar dulu, atau selalu / tanpa dengar?"},
{n:6,type:"mcq",micro:"Cara memutuskan: delegasi",q:"Kadang tim memutuskan dengan menyerahkan keputusan ke...",options:["Anggota yang paling tidak peduli pada hasil keputusan; ia dianggap tidak memihak dan keputusannya terasa netral","Undian tanpa pertimbangan; tak ada yang bisa dituduh memihak dan tim tidak perlu berdiskusi lagi","Satu orang/kelompok kecil yang paling paham bidangnya, dengan masukan dari tim — lalu tim mendukung hasilnya"],answer:2,explain:"Untuk keputusan teknis, menyerahkan ke yang paling ahli (dengan masukan tim) sering lebih baik daripada voting orang yang kurang paham.",hint:"Ke yang paling paham (dengan masukan tim), atau undian / yang cuek?"},
{n:7,type:"mcq",micro:"Mendengar semua sebelum memutuskan",q:"Sebelum keputusan penting diambil, penting memastikan...",options:["Setiap anggota sudah punya kesempatan menyampaikan pendapat & kekhawatirannya","Anggota yang paling vokal sudah bicara dan dianggap mewakili yang lain","Keputusan sudah dibuat lebih dulu, jadi rapat tinggal mengumumkannya kepada anggota"],answer:0,explain:"Keputusan yang dibuat sebelum semua sempat bicara terasa tidak adil & sering melewatkan informasi penting.",hint:"Semua sempat bicara, atau hanya yang vokal?"},
{n:8,type:"mcq",micro:"Kriteria keputusan",q:"Agar keputusan tim tidak sekadar 'suka/tidak suka', tim bisa...",options:["Serahkan pada perasaan masing-masing anggota; keputusan tepat dianggap yang terasa enak bagi mayoritas","Sepakati dulu kriteria penilaian (mis. biaya, waktu, dampak, risiko), lalu nilai tiap pilihan dengan kriteria itu","Pilih yang paling menarik dan menyenangkan saat rapat berlangsung, tanpa membandingkannya dengan patokan tertentu"],answer:1,explain:"Kriteria yang disepakati membuat keputusan lebih objektif & mudah dijelaskan.",hint:"Kriteria disepakati lalu nilai, atau perasaan sesaat?"},
{n:9,type:"order",micro:"Proses keputusan bersama",q:"Urutkan langkah mengambil keputusan tim yang penting.",items:["Perjelas keputusan apa yang perlu diambil & kapan batasnya","Kumpulkan pilihan/opsi & informasi yang relevan","Dengar pendapat & kekhawatiran tiap anggota; nilai opsi dengan kriteria","Putuskan lewat cara yang disepakati (konsensus/voting/delegasi); catat & komunikasikan"],answer:[0,1,2,3],explain:"Perjelas → kumpulkan opsi → dengar semua & nilai → putuskan lewat cara disepakati & catat.",hint:"Apa yang diperjelas paling awal?"},
{n:10,type:"mcq",micro:"Setelah keputusan diambil",q:"Setelah tim mengambil keputusan bersama, anggota yang tadinya tidak setuju sebaiknya...",options:["Menyabotase keputusan diam-diam sebagai pelampiasan kesal, lalu menunggu pilihanmu terbukti lebih baik","Terus mengungkit ketidaksetujuannya sampai tim kelelahan dan mau meninjau ulang","Mendukung keputusan itu & menjalankannya dengan baik ('tidak setuju, tetap komit')"],answer:2,explain:"Menghormati proyek berarti menerima hasil dari proses yang adil, meski bukan pilihanmu.",hint:"Dukung keputusan, atau sabotase / ungkit?"},
{n:11,type:"tf",micro:"Keputusan bersama tidak berarti bulat",q:"Benar atau Salah: Keputusan bersama tidak selalu berarti semua anggota setuju 100% — sering cukup bahwa semua didengar & keputusan diambil lewat cara yang disepakati adil.",answer:true,explain:"Memaksakan kesepakatan bulat sering membuat tim macet. Yang penting: proses adil & semua mendukung hasilnya.",hint:"Harus bulat 100%, atau dengar semua + cara adil?"},
{n:12,type:"tf",micro:"Keputusan cepat selalu lebih baik?",q:"Benar atau Salah: Untuk keputusan besar & sulit dibalik, mengambil keputusan secepat mungkin tanpa mendengar semua pendapat selalu lebih baik daripada meluangkan waktu berdiskusi.",answer:false,explain:"Sebaliknya, keputusan besar yang sulit dibalik layak diberi waktu diskusi & pertimbangan. Keputusan cepat cocok untuk hal kecil/reversibel.",hint:"Keputusan besar butuh diskusi, atau selalu secepat mungkin?"},
{n:13,type:"mcq",micro:"Keputusan reversibel vs tidak",q:"Keputusan yang mudah dibalik (mis. 'coba warna A dulu') dibanding yang sulit dibalik (mis. 'pilih topik proyek'):",options:["Yang mudah dibalik bisa diputuskan cepat & dicoba; yang sulit dibalik layak lebih hati-hati & melibatkan lebih banyak pertimbangan","Keduanya butuh proses yang sama panjangnya, agar tim konsisten dan tidak membeda-bedakan keputusan","Yang mudah dibalik justru butuh rapat panjang dan pertimbangan berat, sedangkan yang sulit dibalik cukup diputuskan cepat"],answer:0,explain:"Sesuaikan seberapa hati-hati proses dengan seberapa besar & permanen dampaknya.",hint:"Sesuaikan proses dengan dampak, atau proses sama untuk semua?"},
{n:14,type:"mcq",micro:"Menyampaikan pendapat dalam keputusan",q:"Cara menyampaikan pilihanmu di rapat keputusan yang membantu:",options:["Diam saja meski punya pendapat kuat, supaya rapat lancar dan tak ada yang terganggu","'Aku condong ke opsi B karena... Tapi aku terbuka mendengar kekhawatiran soal itu.'","'Pokoknya harus B. Nggak ada opsi lain yang perlu dibahas, aku yakin ini yang paling benar.'"],answer:1,explain:"Menyampaikan pilihan + alasan + keterbukaan membantu tim menimbang, bukan sekadar adu suara.",hint:"Pilihan + alasan + terbuka, atau memaksa / diam?"},
{n:15,type:"mcq",micro:"Keputusan & informasi",q:"Kalau tim akan memutuskan tapi informasi penting masih kurang (mis. belum tahu anggaran), sebaiknya...",options:["Putuskan saja dengan menebak; mencari informasi hanya membuang waktu yang terbatas","Tunda tanpa batas waktu sampai informasinya lengkap dan seluruh risiko keputusan itu hilang dari pandangan","Cari dulu informasi itu bila memungkinkan, atau buat keputusan sementara yang bisa disesuaikan"],answer:2,explain:"Keputusan yang dibuat tanpa informasi kunci sering harus diulang. Cari info dulu bila ada waktu.",hint:"Cari info dulu / keputusan sementara, atau tebak / tunda selamanya?"},
{n:16,type:"mcq",micro:"Peran koordinator dalam keputusan",q:"Peran koordinator saat tim mengambil keputusan bersama:",options:["Memfasilitasi: memastikan semua didengar, menjaga diskusi fokus, & memandu proses ke keputusan — bukan memaksakan pilihannya","Memutuskan sendiri pilihan yang menurutnya paling tepat lalu mengumumkannya kepada anggota tanpa perlu mendengarkan tanggapan dari mereka","Membiarkan diskusi berjalan kacau tanpa arah dan tanpa batas waktu; tugas koordinator hanya mencatat apa yang dikatakan oleh peserta"],answer:0,explain:"Koordinator memandu proses agar adil & efisien, tidak mendominasi hasilnya.",hint:"Memfasilitasi proses adil, atau memaksakan / membiarkan kacau?"},
{n:17,type:"mcq",micro:"Mengakomodasi minoritas",q:"Ketika sebuah keputusan diambil lewat voting & ada yang kalah suara, sikap tim yang baik:",options:["Batalkan keputusan itu dan mulai membahas dari awal lagi untuk menenangkan anggota yang khawatir, walau waktu tim terbuang","Akui kekhawatiran mereka, catat, & bila memungkinkan sesuaikan sebagian keputusan untuk mengurangi kekhawatiran itu","Abaikan sepenuhnya; mereka kalah suara dan sebaiknya menerima hasil tanpa mengeluh, lalu tim lanjut bekerja"],answer:1,explain:"Suara minoritas yang beralasan sering menangkap risiko. Mengakomodasi sebagian menjaga tim tetap solid.",hint:"Akui + sesuaikan sebagian, atau abaikan / batalkan?"},
{n:18,type:"mcq",micro:"Keputusan & tanggung jawab",q:"Setelah keputusan bersama diambil, tanggung jawab atas hasilnya...",options:["Hanya milik anggota yang paling mendorong keputusan itu, dan dia sendiri menanggung akibatnya","Tak seorang pun bertanggung jawab; diambil bersama, jadi hasil buruk sulit ditagih","Ditanggung bersama oleh tim — bukan hanya oleh yang mengusulkan atau koordinator"],answer:2,explain:"'Kita memutuskan ini bersama, jadi kita hadapi hasilnya bersama' — termasuk bila ternyata keliru.",hint:"Ditanggung bersama, atau satu orang / tidak ada?"},
{n:19,type:"mcq",micro:"Mencatat keputusan",q:"Menuliskan keputusan tim (apa yang diputuskan, kenapa, siapa mengerjakan apa) berguna karena...",options:["Mencegah 'kita kan sepakat...' yang berbeda-beda & menjadi acuan saat menjalankan","Membuat tim terlalu formal dan kaku, dan anggota takut mengambil keputusan dan berinisiatif","Tidak ada gunanya; anggota biasanya ingat sendiri apa yang disepakati"],answer:0,explain:"Keputusan lisan mudah diingat berbeda. Catatan singkat menghentikan perdebatan tentang 'apa yang tadi diputuskan'.",hint:"Acuan yang jelas, atau terlalu formal?"},
{n:20,type:"open",micro:"Merancang proses keputusan",q:"Timmu (5 orang) harus memutuskan topik untuk proyek besar 4 minggu — keputusan yang sulit dibalik. Ada 4 usulan topik dari berbagai anggota. Rancang proses bagaimana tim mengambil keputusan ini secara adil & matang (minimal 5 langkah), dan jelaskan pilihanmu.",explain:"Jawaban baik: perjelas keputusan & tenggat + akui ini sulit dibalik, tiap pengusul menjelaskan opsinya, sepakati kriteria bersama, nilai tiap opsi dengan kriteria (objektif), beri semua kesempatan menyampaikan condong & kekhawatiran, putuskan lewat konsensus bila ada yang unggul / voting bila terbagi (setelah semua didengar) + hargai pengusul yang kalah, catat keputusan + alasan + langkah — dengan penjelasan kenapa proses berkriteria cocok untuk keputusan besar yang sulit dibalik.",hint:"Perjelas + akui sulit dibalik → pengusul jelaskan opsi → sepakati kriteria → nilai objektif → dengar condong & kekhawatiran semua → konsensus/voting setelah didengar → catat alasan + langkah.",sample:"(1) Perjelas dulu: kita perlu memilih SATU topik hari ini karena minggu depan sudah harus mulai; keputusan ini sulit diubah nanti, jadi kita luangkan waktu cukup. (2) Minta tiap pengusul menjelaskan topiknya singkat: apa isinya, kenapa menarik, & apa yang dibutuhkan (data, sumber, kesulitan). Yang lain menyimak & boleh bertanya untuk memperjelas, belum menilai. (3) Sepakati kriteria penilaian bersama, misalnya: (a) apakah bisa diselesaikan dalam 4 minggu dengan sumber yang kita punya; (b) apakah datanya bisa didapat; (c) seberapa menarik/kuat untuk penilaian; (d) apakah cocok dengan kekuatan tim. (4) Nilai tiap topik dengan kriteria itu bersama-sama (bisa pakai tabel sederhana atau diskusi), sehingga terlihat topik mana yang paling kuat secara objektif, bukan sekadar yang paling disukai. (5) Beri tiap anggota kesempatan menyampaikan condong ke mana & kekhawatirannya. (6) Ambil keputusan: kalau setelah penilaian ada satu topik yang jelas unggul, kita coba capai konsensus ('semua bisa dukung ini?'). Kalau masih terbagi 2-3, kita voting dengan syarat semua sudah didengar; pengusul topik yang tidak terpilih tetap kita hargai & libatkan. (7) Catat keputusan + alasannya + langkah awal, dan tegaskan semua mendukung. Penjelasan: karena ini keputusan besar & sulit dibalik, aku pakai proses berkriteria (bukan voting mentah) supaya matang & bisa dijelaskan; aku pastikan semua pengusul & semua anggota didengar supaya adil; dan aku catat alasannya supaya kalau di tengah jalan ada yang ragu, kita ingat kenapa memilih ini."},
{n:21,type:"classify",micro:"Cara memutuskan & kapan cocok",q:"Cocokkan tiap cara memutuskan dengan situasi yang paling pas: 'Konsensus', 'Voting', 'Delegasi ke yang ahli', atau 'Koordinator putuskan cepat'.",items:["Keputusan besar yang butuh dukungan penuh semua anggota untuk berhasil","Pilihan sudah jelas & waktu terbatas, tim setuju pakai suara terbanyak","Keputusan teknis di bidang yang hanya satu-dua anggota kuasai","Hal kecil/mendesak yang tidak bisa menunggu rapat"],groups:["Konsensus","Voting","Delegasi ke yang ahli","Koordinator putuskan cepat"],answer:{"Konsensus":["Keputusan besar yang butuh dukungan penuh semua anggota untuk berhasil"],"Voting":["Pilihan sudah jelas & waktu terbatas, tim setuju pakai suara terbanyak"],"Delegasi ke yang ahli":["Keputusan teknis di bidang yang hanya satu-dua anggota kuasai"],"Koordinator putuskan cepat":["Hal kecil/mendesak yang tidak bisa menunggu rapat"]},explain:"Tidak ada satu cara memutuskan yang terbaik untuk semua situasi. Pilih sesuai besarnya keputusan, waktu, & siapa yang paling paham.",hint:"Cara memutuskan disesuaikan dengan situasi, bukan satu untuk semua."},
{n:22,type:"mcq",micro:"Konsensus vs kompromi",q:"Beda 'konsensus' & 'kompromi':",options:["Konsensus berarti satu pihak menang dan pihak lain menyerah; kompromi berarti semua puas dengan hasilnya, tanpa perlu melepas keinginan","Konsensus: solusi yang semua benar-benar bisa dukung. Kompromi: tiap pihak melepas sebagian keinginan, kadang tak ada yang benar-benar puas","Keduanya sama; sama-sama berarti tim memilih jalan tengah yang membuat tiap pihak melepas sebagian keinginannya, lalu menjalankannya bersama-sama"],answer:1,explain:"Konsensus butuh diskusi lebih dalam & sering menghasilkan solusi yang lebih kreatif daripada sekadar 'ketemu di tengah'.",hint:"Semua bisa dukung penuh vs ketemu di tengah, atau sama?"},
{n:23,type:"mcq",micro:"Ilusi konsensus",q:"'Ilusi konsensus' terjadi ketika...",options:["Tim sepakat setelah anggota menyampaikan pendapat terbuka dan seluruh keraguan dibahas tuntas, sebelum memutuskan","Ada perdebatan sehat, tiap anggota berani menyanggah dan akhirnya sungguh-sungguh yakin dengan pilihan","Semua diam & mengangguk padahal sebenarnya banyak yang ragu — sehingga keputusan buruk lolos tanpa diperiksa"],answer:2,explain:"Diam bukan berarti setuju. Koordinator yang baik bertanya 'ada yang punya keraguan?' & menyambut kejujuran.",hint:"Diam & mengangguk padahal ragu, atau benar-benar sepakat?"},
{n:24,type:"mcq",micro:"Groupthink dalam keputusan",q:"'Groupthink' membuat keputusan tim buruk karena...",options:["Anggota menahan pendapat berbeda demi keharmonisan, sehingga risiko & kelemahan pilihan tidak pernah dibahas","Terlalu banyak perdebatan panjang sehingga keputusan tak selesai dan anggota kehabisan tenaga untuk lanjut","Anggota terlalu jujur menyampaikan kekhawatiran, sehingga suasana tegang dan keputusan baik tak bisa diambil"],answer:0,explain:"Sengaja meminta 'siapa yang melihat risiko di pilihan ini?' melawan groupthink.",hint:"Menahan pendapat demi harmoni, atau terlalu banyak debat?"},
{n:25,type:"mcq",micro:"Peran 'penantang' (devil's advocate)",q:"Menugaskan seseorang untuk sengaja mencari kelemahan pilihan favorit tim berguna karena...",options:["Membuat tim bertengkar; pilihan favorit diserang terus, dan keputusan makin sulit","Memaksa tim menghadapi risiko & kelemahan sebelum memutuskan, bukan setelah terlambat","Membuat rapat lebih lama tanpa manfaat; kelemahan yang dicari hanya hal kecil"],answer:1,explain:"'Devil's advocate' resmi membuat kritik terasa aman (itu tugasnya) & menangkap lubang sebelum keputusan final.",hint:"Menghadapi risiko lebih awal, atau memperlama?"},
{n:26,type:"mcq",micro:"Keputusan & waktu diskusi",q:"Menetapkan batas waktu untuk diskusi keputusan ('kita bahas 15 menit lalu putuskan') membantu karena...",options:["Membuat orang tergesa-gesa dan ceroboh; tekanan waktu biasanya menghasilkan pilihan buruk","Tidak perlu; diskusi harus berjalan tanpa batas waktu dan setiap anggota bisa bicara","Mencegah diskusi tanpa akhir & memaksa tim bergerak, sambil tetap memberi ruang mendengar"],answer:2,explain:"Batas waktu yang wajar menyeimbangkan 'dengar semua' dengan 'jangan macet'.",hint:"Mencegah macet, atau membuat ceroboh?"},
{n:27,type:"tf",micro:"Keputusan bersama butuh cara yang disepakati",q:"Benar atau Salah: Tim tidak perlu menyepakati cara mengambil keputusan di awal; membahas caranya setiap kali ada keputusan sulit sudah cukup.",answer:false,explain:"Sebaliknya, tim yang tidak pernah menyepakati cara memutuskan sering bertengkar soal 'kenapa kamu putusin sendiri' atau 'kenapa harus voting' justru saat keputusan sedang sulit.",hint:"Sepakati cara di awal, atau bahas caranya tiap kali?"},
{n:28,type:"tf",micro:"Suara terbanyak selalu keputusan terbaik?",q:"Benar atau Salah: Dalam keputusan tim, pilihan yang didukung suara terbanyak selalu merupakan pilihan yang paling tepat & terbaik.",answer:false,explain:"Sebaliknya, mayoritas bisa salah — terutama bila keputusan butuh keahlian, atau bila mayoritas belum mendengar informasi/kekhawatiran penting. Voting adalah alat, bukan jaminan kebenaran.",hint:"Suara terbanyak = pasti terbaik, atau alat yang bisa keliru?"},
{n:29,type:"mcq",micro:"Keputusan & kesetaraan suara",q:"Dalam diskusi keputusan, cara agar suara anggota pendiam tidak tenggelam:",options:["Putar giliran ('semua sebut pendapatnya'), atau minta menulis pendapat dulu sebelum diskusi lisan, atau tanyakan mereka secara khusus","Biarkan anggota yang mau berbicara saja yang menyampaikan pendapat; yang diam berarti tak punya pendapat penting","Anggap diamnya berarti setuju dengan pendapat yang sudah disampaikan, tak perlu ditanyai, dan keputusan bisa diambil"],answer:0,explain:"Tanpa usaha sengaja, keputusan tim sering hanya mencerminkan pendapat yang paling vokal, bukan yang terbaik.",hint:"Putar giliran / tulis dulu / tanya khusus, atau biarkan / anggap setuju?"},
{n:30,type:"order",micro:"Menilai beberapa opsi dengan kriteria",q:"Urutkan langkah menilai 3 opsi keputusan dengan kriteria.",items:["Sepakati kriteria penilaian (mis. biaya, waktu, dampak, risiko)","Untuk tiap opsi, nilai bagaimana ia memenuhi tiap kriteria","Bandingkan hasilnya; lihat opsi mana yang paling kuat secara keseluruhan","Diskusikan hasil & putuskan; catat alasannya"],answer:[0,1,2,3],explain:"Kriteria → nilai tiap opsi → bandingkan → putuskan & catat. Ini membuat keputusan objektif & bisa dijelaskan.",hint:"Apa yang disepakati sebelum menilai opsi?"},
{n:31,type:"mcq",micro:"Keputusan & rasa memiliki",q:"Mengapa anggota lebih mendukung keputusan yang ikut mereka buat?",options:["Tidak ada hubungannya; rasa dukungan lebih ditentukan oleh hasil keputusan daripada prosesnya","Mereka memahami alasannya, merasa pendapatnya dihargai, & merasa ikut bertanggung jawab atas hasilnya","Mereka takut pada koordinator dan merasa harus menurut, tidak ingin dimusuhi tim di kemudian hari"],answer:1,explain:"Keputusan yang dipaksakan sering hanya dituruti setengah hati. Yang dibuat bersama dijalankan sepenuh hati.",hint:"Paham alasan + merasa dihargai + ikut bertanggung jawab, atau takut?"},
{n:32,type:"tf",micro:"Keputusan cepat untuk hal kecil",q:"Benar atau Salah: Bahkan untuk hal-hal kecil & mudah dibalik, tim sebaiknya selalu merapatkan & memutuskan bersama demi keadilan.",answer:false,explain:"Sebaliknya, merapatkan setiap detail kecil melelahkan & membuang waktu. Untuk hal kecil/mudah dibalik, koordinator (atau yang terdekat) memutuskan cepat lebih efisien; simpan proses bersama untuk yang penting.",hint:"Hal kecil diputuskan cepat, atau semua wajib rapat?"},
{n:33,type:"mcq",micro:"Keputusan & pengecekan asumsi",q:"Sebelum memfinalkan keputusan, pertanyaan yang berguna:",options:["'Semua setuju kan? Baik, kita anggap selesai dan langsung dijalankan, tidak perlu dibahas lagi.'","'Siapa yang mau bertanggung jawab kalau keputusan ini gagal?' — untuk memastikan jelas siapa yang disalahkan","'Apa yang kita asumsikan benar? Apa yang bisa membuat keputusan ini gagal? Apa rencana bila itu terjadi?'"],answer:2,explain:"Menguji asumsi & memikirkan 'bagaimana bila gagal' membuat keputusan lebih tahan.",hint:"Uji asumsi & rencana cadangan, atau 'setuju kan, selesai'?"},
{n:34,type:"mcq",micro:"Keputusan yang bisa dicoba dulu",q:"Untuk keputusan yang tidak yakin, pendekatan yang bijak:",options:["Coba dalam skala kecil / sementara dulu ('kita pakai cara A untuk minggu ini, lalu evaluasi'), bukan langsung berkomitmen penuh","Langsung berkomitmen penuh pada satu pilihan dan berharap benar; ragu-ragu hanya membuang semangat dan waktu","Tidak memutuskan apa-apa sampai semua anggota yakin 100%; keputusan yang diambil dalam keraguan pasti salah"],answer:0,explain:"Keputusan yang bisa 'diuji dulu' mengurangi risiko: kamu belajar dari percobaan kecil sebelum melangkah besar.",hint:"Coba kecil / sementara dulu, atau komitmen penuh langsung?"},
{n:35,type:"mcq",micro:"Keputusan & konflik kepentingan",q:"Bila sebuah keputusan menguntungkan satu anggota secara pribadi (mis. memilih dia jadi ketua panitia), sikap yang menjaga keadilan:",options:["Abaikan saja konflik kepentingan itu; anggota dianggap dewasa dan bisa bersikap adil walau keputusannya menguntungkan dirinya sendiri","Anggota itu menyampaikan pendapat tapi tidak ikut memutuskan/voting untuk hal yang menguntungkannya langsung; tim memutuskan berdasarkan kepentingan bersama","Anggota itu memutuskan sendiri; 'dia yang paling paham' dengan kebutuhan & beban tugasnya, jadi tidak perlu ada voting dari anggota lain"],answer:1,explain:"Menyadari & mengelola konflik kepentingan menjaga keputusan tim tetap dipercaya adil.",hint:"Sampaikan tapi tidak ikut memutuskan hal yang menguntungkannya, atau abaikan?"},
{n:36,type:"mcq",micro:"Keputusan & data vs perasaan",q:"Keputusan tim yang baik biasanya mempertimbangkan...",options:["Hanya data dan fakta seperti biaya dan waktu, sedangkan perasaan anggota diabaikan sebagai kurang objektif","Hanya perasaan dan selera anggota, sedangkan data seperti biaya dan waktu diabaikan sebagai kurang menyenangkan","Data & fakta (biaya, waktu, kemampuan) DAN perasaan/nilai anggota (apa yang penting bagi mereka)"],answer:2,explain:"Keputusan yang hanya berdasar data terasa dingin & kurang didukung; yang hanya berdasar perasaan sering tidak realistis. Keduanya perlu.",hint:"Data + perasaan/nilai, atau salah satu?"},
{n:37,type:"tf",micro:"Keputusan bersama bisa dilatih",q:"Benar atau Salah: Kemampuan tim untuk mengambil keputusan bersama dengan baik — mendengar semua, memakai kriteria, memilih cara yang tepat, & mendukung hasilnya — bisa dilatih & membaik dari proyek ke proyek.",answer:true,explain:"Tim yang merefleksikan 'bagaimana kita memutuskan tadi & apa yang bisa lebih baik' menjadi makin efektif.",hint:"Bisa dilatih & membaik, atau tetap?"},
{n:38,type:"mcq",micro:"Keputusan yang tertunda terus",q:"Tim yang terus menunda keputusan penting ('nanti aja dibahas lagi') berisiko...",options:["Kehabisan waktu & akhirnya terpaksa memutuskan buru-buru dengan pilihan yang lebih buruk, atau keputusan diambil oleh keadaan","Membuat keputusan lebih baik; tim punya lebih banyak waktu berpikir dan semua pilihan bisa dicoba satu per satu","Tak ada risiko; keputusan yang ditunda biasanya menjadi lebih mudah saat tenggat sudah dekat dan anggota lebih tenang serta kompak"],answer:0,explain:"Tidak memutuskan juga adalah keputusan — biasanya keputusan yang buruk. Tetapkan batas waktu.",hint:"Terpaksa buru-buru nanti, atau keputusan lebih baik?"},
{n:39,type:"mcq",micro:"Keputusan & mengubahnya nanti",q:"Bila di tengah jalan muncul informasi baru yang menunjukkan keputusan tim keliru, sikap yang matang:",options:["Salahkan anggota yang mengusulkan keputusan lama di depan tim, dan tunjukkan siapa yang bertanggung jawab atas kekeliruan itu","Bahas bersama: apakah keputusan perlu diubah? Mengubah keputusan berdasarkan info baru bukan tanda plin-plan, tapi tanda bijak","Pertahankan keputusan lama demi konsistensi walau jelas keliru; mengubahnya menunjukkan tim plin-plan dan tak punya pendirian"],answer:1,explain:"Keputusan melayani tujuan. Bila info baru mengubah gambaran, meninjau keputusan adalah hal yang benar.",hint:"Bahas & ubah bila perlu, atau pertahankan demi konsistensi / menyalahkan?"},
{n:40,type:"open",micro:"Menganalisis keputusan yang buruk",q:"Sebuah tim memutuskan topik proyek dalam 3 menit: ketua mengusulkan topik favoritnya, bertanya 'setuju ya?', semua diam & mengangguk (padahal dua anggota ragu), lalu langsung mulai. Dua minggu kemudian ternyata datanya tidak bisa didapat & proyek harus diulang. Jelaskan minimal 4 kesalahan dalam cara tim ini mengambil keputusan, lalu tulis proses yang seharusnya.",explain:"Jawaban baik menyebut minimal 4 kesalahan (hanya satu opsi, tanpa kriteria, ilusi konsensus / keraguan tak terdengar, terlalu cepat untuk keputusan besar, ketua mendominasi) dan menulis proses yang benar: perjelas + luangkan waktu, kumpulkan beberapa opsi, sepakati kriteria, nilai bersama (menangkap masalah data), dengar condong & kekhawatiran + tanya keraguan, putuskan lewat cara adil, catat.",hint:"Cari: satu opsi saja, tanpa kriteria, ilusi konsensus, terlalu cepat, ketua dominan. Tulis proses: opsi + kriteria + nilai bersama + dengar keraguan + cara adil + catat.",sample:"Kesalahan: (1) Hanya satu opsi (topik favorit ketua) yang dipertimbangkan — tidak ada pilihan lain yang dikumpulkan atau dibandingkan. (2) Tidak ada kriteria penilaian; tim tidak memeriksa apakah topik itu realistis (data bisa didapat? selesai dalam waktu yang ada?). (3) 'Setuju ya?' yang dijawab diam menghasilkan ilusi konsensus — dua anggota yang ragu tidak diberi ruang atau tidak berani menyuarakannya, sehingga keraguan penting tidak terdengar. (4) Prosesnya terlalu cepat (3 menit) untuk keputusan besar yang sulit dibalik. (5) Ketua mendominasi keputusan alih-alih memfasilitasi. Proses yang seharusnya: (a) Perjelas bahwa ini keputusan besar & sulit diubah, jadi luangkan waktu cukup. (b) Kumpulkan beberapa usulan topik dari anggota, tiap pengusul menjelaskan singkat. (c) Sepakati kriteria: bisa selesai dalam waktu tersedia, data bisa didapat, cocok dengan kekuatan tim, cukup menarik. (d) Nilai tiap topik dengan kriteria itu bersama-sama — di sini masalah 'data tidak bisa didapat' akan ketahuan sebelum mulai. (e) Beri tiap anggota kesempatan menyampaikan condong & kekhawatiran; ketua secara khusus bertanya 'ada yang ragu?' dan menyambutnya. (f) Putuskan lewat konsensus bila ada yang unggul, atau voting setelah semua didengar. (g) Catat keputusan + alasan + langkah awal."},
{n:41,type:"mcq",micro:"Skenario: keputusan mendesak, tim tersebar",q:"Tim harus memutuskan sesuatu segera tapi tidak semua bisa dihubungi. Cara yang wajar:",options:["Tunggu sampai semua anggota bisa berkumpul meski tenggat lewat; keputusan tidak boleh diambil tanpa seluruh anggota","Putuskan sendiri secepatnya dan tidak memberi tahu anggota; yang penting urusannya selesai dan tak sempat diprotes","Kumpulkan pendapat yang bisa dihubungi, ambil keputusan sementara yang masuk akal, & kabari semua secepatnya untuk masukan/revisi"],answer:2,explain:"Keputusan sementara + transparansi lebih baik daripada macet total atau keputusan diam-diam.",hint:"Sementara + kabari semua, atau macet / diam-diam?"},
{n:42,type:"mcq",micro:"Skenario: tim terbagi rata (2-2-1)",q:"Setelah diskusi, tim terbagi: 2 pilih A, 2 pilih B, 1 ragu. Cara maju:",options:["Gali lebih dalam: apa kekhawatiran tiap sisi? adakah opsi C yang menggabungkan? bila buntu, serahkan ke penanggung jawab bidang atau coba A dulu lalu evaluasi","Berdebat sampai satu sisi lelah dan menyerah; pihak yang bertahan paling lama dianggap paling yakin, lalu keberatan pihak yang kalah tidak dicatat","Batalkan proyek dan mulai lagi dengan topik lain, lalu bagi tim menjadi dua kelompok kerja terpisah agar tidak ada yang merasa kalah"],answer:0,explain:"Kebuntuan seimbang butuh pendalaman (cari opsi ketiga, pahami kekhawatiran) atau mekanisme pemecah (peragu memutuskan, coba lalu evaluasi).",hint:"Gali lebih dalam + mekanisme pemecah, atau debat sampai menyerah / batal?"},
{n:43,type:"mcq",micro:"Skenario: kamu tidak setuju tapi kalah suara",q:"Tim voting & pilihanmu kalah 4-1. Kamu masih khawatir. Sikap yang matang:",options:["Terus mengungkit bahwa pilihanmu lebih baik di setiap rapat berikutnya, sampai tim bersedia memutar balik keputusan yang sudah disepakati lewat voting","Sampaikan kekhawatiranmu sekali lagi dengan jelas agar tercatat; minta agar bagian yang kamu khawatirkan dipantau; lalu dukung keputusan & beri yang terbaik","Menolak mengerjakan bagianmu dalam rencana yang dipilih, sebagai protes bahwa pilihanmu tidak dipakai dan kekhawatiranmu tidak dianggap penting oleh tim"],answer:1,explain:"Menyuarakan + minta pemantauan + tetap mendukung adalah cara menghormati proses sambil tetap bertanggung jawab.",hint:"Suarakan + minta dipantau + dukung, atau menolak / mengungkit?"},
{n:44,type:"mcq",micro:"Skenario: satu anggota selalu memaksakan pilihannya",q:"Seorang anggota selalu mendominasi keputusan & yang lain jadi pasif. Sikap tim:",options:["Menyerah dan ikut dia saja untuk menghindari pertengkaran, walaupun pendapat anggota lain tidak dipertimbangkan dalam keputusan, lalu berharap hasilnya baik","Semua anggota ikut memaksakan pilihan masing-masing dengan suara keras, dan yang paling keras suaranya yang akhirnya diikuti oleh seluruh tim","Sepakati proses keputusan terstruktur: kumpulkan opsi, semua bicara bergiliran, nilai dengan kriteria, baru putuskan — bukan siapa yang paling keras"],answer:2,explain:"Struktur proses (opsi → giliran → kriteria → putuskan) menetralkan dominasi tanpa konfrontasi langsung.",hint:"Proses terstruktur, atau menyerah / balas memaksa?"},
{n:45,type:"order",micro:"Memimpin rapat pengambilan keputusan",q:"Urutkan langkah memimpin rapat 20 menit untuk satu keputusan penting.",items:["Nyatakan keputusan apa yang perlu diambil, kriteria, & batas waktu diskusi","Kumpulkan opsi & minta penjelasan singkat tiap opsi","Putar giliran: tiap anggota menyampaikan condong & kekhawatiran","Nilai opsi dengan kriteria; putuskan lewat cara disepakati; rangkum keputusan + langkah + siapa mengerjakan apa"],answer:[0,1,2,3],explain:"Nyatakan + kriteria + batas → opsi → giliran pendapat → nilai & putuskan & rangkum. Struktur menjaga rapat efisien & adil.",hint:"Apa yang dinyatakan di awal sebelum mengumpulkan opsi?"},
{n:46,type:"mcq",micro:"Skenario: keputusan yang kamu usulkan ternyata keliru",q:"Keputusan tim mengikuti usulmu, lalu ternyata keliru & merugikan. Sikap:",options:["Akui: 'Usulku ternyata kurang tepat, maaf. Ayo kita cari cara memperbaiki.' — tanpa berlebihan menyalahkan diri, fokus ke solusi","Bersikeras usulmu sebenarnya benar dan kerugian terjadi karena anggota lain tak menjalankannya dengan baik, bukan kesalahanmu","Diam dan berharap tak ada yang ingat itu usulmu, lalu mengalihkan pembicaraan ke hal lain untuk menghindari pertanyaan"],answer:0,explain:"Mengakui + fokus solusi mengubah kesalahan jadi pembelajaran tim, & mendorong orang lain berani mengusulkan juga.",hint:"Akui + fokus solusi, atau bersikeras / diam?"},
{n:47,type:"mcq",micro:"Skenario: keputusan soal hal yang kamu tidak paham",q:"Tim memutuskan soal hal teknis yang kamu tidak kuasai. Sikap yang bertanggung jawab:",options:["Diam total dan tidak ikut dalam keputusan itu, karena kamu tidak menguasainya dan pendapatmu tak akan membantu tim, jadi lebih baik menunggu hasilnya saja","Ajukan pertanyaan untuk memahami cukup agar bisa ikut menimbang; percayakan detail teknis ke yang ahli tapi tetap perhatikan dampak keseluruhannya","Voting asal-asalan mengikuti suara terbanyak karena 'kan keputusannya bareng-bareng', tanpa mencoba memahami apa dampak dari pilihan yang diambil"],answer:1,explain:"Kamu tidak perlu jadi ahli untuk ikut keputusan — tapi kamu perlu memahami cukup untuk menilai dampaknya bagi tim.",hint:"Tanya untuk paham + percayakan detail ke ahli, atau voting asal / diam total?"},
{n:48,type:"mcq",micro:"Skenario: keputusan berulang yang selalu diperdebatkan",q:"Tim selalu berdebat panjang setiap memutuskan hal serupa (mis. tiap minggu debat 'rapat di mana'). Solusi:",options:["Terus berdebat tiap minggu soal waktu dan tempat rapat, karena situasi anggota berubah-ubah tiap pekan dan tim perlu menyesuaikan","Berhenti rapat dan mengerjakan semuanya lewat pesan pribadi, supaya tak perlu menentukan jadwal dan tempat lagi, karena itu lebih praktis","Buat aturan/default sekali: 'Rapat selalu di ruang X hari Rabu kecuali ada halangan' — sehingga tidak perlu diputuskan ulang tiap kali"],answer:2,explain:"Keputusan berulang sebaiknya jadi aturan tetap ('default'), bukan diputuskan dari nol setiap kali.",hint:"Buat default sekali, atau debat tiap minggu?"},
{n:49,type:"mcq",micro:"Skenario: keputusan darurat oleh koordinator",q:"Koordinator mengambil keputusan mendesak sendiri (tim tak bisa dihubungi) & seorang anggota marah 'kenapa nggak nunggu kami?'. Sikap koordinator:",options:["Jelaskan: 'Ini harus diputuskan dalam 1 jam & kalian tak bisa dihubungi. Aku ambil pilihan paling aman. Kalau ada masukan, kita sesuaikan yang belum terlanjur.'","Bersikeras 'aku kan koordinator, terserah aku', tanpa menjelaskan alasan atau mendengarkan keberatan anggota, lalu menganggapnya selesai tanpa dibahas ulang","Membatalkan keputusan itu dan menyalahkan diri sendiri berlebihan di depan anggota, walau keputusannya tepat, lalu meminta tim memutuskan ulang dari awal"],answer:0,explain:"Keputusan darurat sepihak itu sah bila benar mendesak — asalkan dijelaskan transparan & terbuka disesuaikan.",hint:"Jelaskan situasi + terbuka disesuaikan, atau 'terserah aku' / membatalkan?"},
{n:50,type:"open",micro:"Merancang mekanisme keputusan tim",q:"Kamu ketua tim OSIS 10 orang untuk setahun. Kalian akan sering mengambil keputusan: besar (arah program) & kecil (detail acara), mendesak & tidak. Rancang 'mekanisme pengambilan keputusan' yang akan kalian sepakati di awal — minimal 5 aturan dengan alasan.",explain:"Jawaban baik memuat minimal 5 aturan dengan alasan, mencakup: klasifikasi keputusan (besar/menengah/kecil-mendesak) dengan cara memutuskan berbeda, kriteria untuk keputusan besar, delegasi ke PJ bidang untuk keputusan menengah, keputusan darurat oleh ketua + transparansi, cek keraguan/risiko sebelum finalisasi (anti-groupthink), pencatatan keputusan, 'tidak setuju tetap komit' setelah proses adil, peninjauan bila ada info baru, & evaluasi mekanisme.",hint:"Klasifikasikan keputusan (besar=rapat+kriteria+konsensus/voting; menengah=PJ bidang; kecil-mendesak=ketua+jelaskan), tambah: cek keraguan, catat keputusan, dukung hasil proses adil, tinjau bila ada info baru.",sample:"Mekanisme keputusan tim: (1) Keputusan BESAR (arah program, anggaran besar, hal yang sulit dibalik) dibahas di rapat dengan semua anggota, memakai kriteria yang disepakati, & diputuskan lewat konsensus; bila tak tercapai setelah diskyci cukup, lewat voting suara terbanyak (minimal 6 dari 10 hadir). Alasan: keputusan besar butuh dukungan luas & pertimbangan matang. (2) Keputusan MENENGAH (detail acara, pembagian tugas dalam satu bidang) diputuskan oleh penanggung jawab bidang terkait dengan masukan anggotanya, lalu dilaporkan ke rapat. Alasan: yang paling paham & terlibat langsung yang paling pas memutuskan. (3) Keputusan KECIL & MENDESAK yang tidak bisa menunggu diputuskan oleh ketua (atau PJ bidang), lalu WAJIB dijelaskan ke tim secepatnya & bisa disesuaikan bila belum terlanjur. Alasan: tim tidak boleh macet karena hal kecil, tapi transparansi tetap dijaga. (4) Dalam setiap keputusan besar, sebelum difinalkan, ketua bertanya secara khusus 'ada yang punya keraguan atau melihat risiko?' & memberi ruang aman untuk menjawab. Alasan: mencegah ilusi konsensus & groupthink. (5) Setiap keputusan penting dicatat: apa yang diputuskan, alasannya, siapa mengerjakan apa, & kapan. Alasan: menjadi acuan & mencegah 'kita kan sepakat...' yang berbeda-beda. (6) Setelah keputusan diambil lewat proses yang disepakati, semua anggota mendukung & menjalankannya, meski bukan pilihan pribadinya; kekhawatiran yang tidak terpakai tetap dicatat. (7) Bila muncul informasi baru yang penting, keputusan boleh ditinjau ulang di rapat berikutnya — mengubah keputusan berdasarkan fakta baru bukan plin-plan. (8) Mekanisme ini ditinjau setelah 3 bulan: apakah adil & efisien?"},
{n:51,type:"mcq",micro:"Skenario: keputusan & anggota yang absen",q:"Tim mengambil keputusan besar saat satu anggota tidak bisa hadir. Sikap yang adil:",options:["Sengaja memutuskan hal yang merugikannya karena dia sedang absen, sebagai pelajaran untuk lebih disiplin menghadiri rapat penting berikutnya bersama seluruh tim","Kabari dia hasilnya + alasannya secepatnya, beri kesempatan menyampaikan masukan; bila penting & belum terlanjur, tim boleh menyesuaikan","Anggap dia otomatis setuju dengan semua keputusan karena tidak hadir, jadi tidak perlu diberi tahu hasilnya atau diminta pendapatnya kembali"],answer:1,explain:"Absen tidak menghapus hak anggota untuk didengar. Kabari + beri ruang masukan.",hint:"Kabari + beri ruang masukan, atau anggap setuju / merugikan?"},
{n:52,type:"tf",micro:"Mencatat alasan keputusan",q:"Benar atau Salah: Mencatat alasan di balik keputusan tim adalah pemborosan waktu; cukup catat keputusan akhirnya saja.",answer:false,explain:"Sebaliknya, mencatat MENGAPA (alasan & pertimbangan) mencegah tim membongkar ulang keputusan lama tanpa info baru, & membantu menjelaskan ke pihak luar.",hint:"Catat alasan juga, atau cukup apa yang diputuskan?"},
{n:53,type:"mcq",micro:"Skenario: keputusan yang harus melibatkan pihak luar",q:"Keputusan tim akan memengaruhi kelas/kelompok lain. Sikap yang tepat:",options:["Putuskan sendiri tanpa bertanya dengan alasan 'ini urusan tim kami', dan pihak lain tinggal menyesuaikan diri setelah diumumkan","Tidak memutuskan apa-apa agar pihak lain tidak merasa terganggu, walaupun tim perlu menentukan arah kerjanya segera","Konsultasikan atau libatkan perwakilan pihak yang terdampak sebelum memutuskan, bukan memutuskan sepihak lalu mengejutkan mereka"],answer:2,explain:"Keputusan yang berdampak ke orang di luar tim sebaiknya melibatkan mereka — keputusan yang mengejutkan sering ditolak.",hint:"Libatkan pihak terdampak, atau sepihak / tidak memutuskan?"},
{n:54,type:"mcq",micro:"Skenario: memilih di antara opsi yang semua kurang bagus",q:"Semua opsi keputusan tim punya kelemahan besar & tidak ada yang ideal. Sikap:",options:["Pilih yang kelemahannya paling bisa dikelola / dampaknya paling ringan, sadari trade-off-nya, & siapkan rencana mengurangi kelemahan itu","Menolak memilih sampai ada opsi yang sempurna; memilih yang punya kelemahan dianggap kegagalan tim, lalu menunda keputusan","Pilih acak dengan undian, tanpa menimbang kelemahan atau menyiapkan rencana untuk mengatasinya, lalu jalankan"],answer:0,explain:"Banyak keputusan nyata adalah memilih 'yang paling tidak buruk'. Yang penting: sadar trade-off & kelola risikonya.",hint:"Pilih yang kelemahannya paling terkelola + kelola risiko, atau tunggu sempurna / acak?"},
{n:55,type:"mcq",micro:"Skenario: keputusan & tekanan dari anggota senior",q:"Anggota yang lebih senior menekan tim memilih opsinya. Sikap tim:",options:["Abaikan pendapatnya karena dianggap sok tua, lalu putuskan tanpa mempertimbangkan alasannya, walau mungkin beralasan dan penting bagi tim kita","Hargai pengalamannya & dengarkan alasannya, tapi tetap jalankan proses keputusan yang disepakati (kriteria, semua didengar) — senioritas bukan otomatis hasil","Ikuti pilihan anggota yang lebih senior tanpa membahas alasannya; pengalaman dianggap berarti keputusannya paling tepat, dan yang lain cukup menyetujui"],answer:1,explain:"Pengalaman berharga sebagai masukan, tapi keputusan tim tetap lewat proses adil, bukan tekanan.",hint:"Dengar + tetap jalankan proses adil, atau selalu ikut / abaikan?"},
{n:56,type:"mcq",micro:"Skenario: keputusan cepat yang ternyata perlu lebih hati-hati",q:"Di tengah memutuskan cepat, seorang anggota berkata 'tunggu, ini sebenarnya keputusan besar yang sulit diubah'. Sikap:",options:["Abaikan peringatan itu dan lanjut cepat karena sudah hampir selesai; berhenti hanya membuang waktu","Marah pada anggota yang menyela di tengah proses; ia dianggap mengacaukan rapat dan memperlambat keputusan penting tim","Berhenti sejenak & nilai ulang: benarkah ini keputusan besar? Bila ya, beri waktu & proses yang lebih hati-hati"],answer:2,explain:"Mengenali bahwa sebuah keputusan lebih besar dari yang dikira & menyesuaikan proses adalah tanda tim yang bijak.",hint:"Berhenti & nilai ulang besarnya, atau abaikan / marah?"},
{n:57,type:"tf",micro:"Tidak memutuskan juga keputusan",q:"Benar atau Salah: Ketika tim terus menunda mengambil keputusan, itu sendiri adalah sebuah keputusan — biasanya keputusan untuk membiarkan keadaan atau waktu yang memutuskan, yang sering hasilnya lebih buruk.",answer:true,explain:"Menunda terasa 'aman' tapi sering menghilangkan pilihan terbaik & memaksa keputusan buru-buru di akhir.",hint:"Menunda = keputusan (sering buruk), atau menunda = netral?"},
{n:58,type:"mcq",micro:"Skenario: setelah keputusan, hasil belum kelihatan",q:"Tim sudah memutuskan & menjalankan, tapi hasilnya belum jelas & beberapa mulai ragu. Sikap:",options:["Beri keputusan waktu wajar untuk menunjukkan hasil (sesuai kesepakatan); tinjau di titik yang ditentukan, bukan membongkar tiap ada keraguan sesaat","Bongkar dan ubah keputusan setiap ada anggota yang merasa ragu, walau baru berjalan sehari, untuk membuat anggota nyaman dengan pilihan tim","Larang anggota mempertanyakan keputusan lagi setelah dijalankan, termasuk di titik tinjauan, dan tim harus kompak tanpa ragu sampai proyek berakhir"],answer:0,explain:"Keputusan butuh waktu untuk berbuah. Menetapkan 'kapan kita evaluasi' mencegah pembongkaran berulang & juga kebutaan.",hint:"Beri waktu + tinjau di titik yang ditentukan, atau bongkar tiap keraguan / larang bertanya?"},
{n:59,type:"mcq",micro:"Skenario: keputusan & kelelahan tim",q:"Rapat keputusan sudah 2 jam & semua lelah, keputusan belum diambil. Sikap yang bijak:",options:["Bubar tanpa kesepakatan dan tidak membahas kapan akan dilanjutkan; rapat yang melelahkan sebaiknya segera dibubarkan, lalu lanjut sendiri-sendiri","Sepakati melanjutkan besok saat segar, atau ambil keputusan sementara yang bisa disesuaikan — keputusan penting saat semua lelah cenderung buruk","Paksakan memutuskan sekarang juga meski semua sudah tidak fokus, dan selesaikan malam ini tanpa rapat lagi, walau hasilnya terburu-buru"],answer:1,explain:"Kualitas keputusan menurun saat lelah. Menjadwalkan lanjutan atau keputusan sementara lebih baik.",hint:"Lanjut besok / keputusan sementara, atau paksakan / bubar begitu saja?"},
{n:60,type:"open",micro:"Skenario menyeluruh",q:"Timmu (6 orang) harus memutuskan apakah mengubah rencana proyek di tengah jalan karena muncul kesulitan besar (data yang direncanakan tidak tersedia). Mengubah rencana berarti kerja 2 minggu sebagian terbuang; tidak mengubah berarti hasil akhir mungkin lemah. Tim terbelah. Rancang bagaimana kamu memimpin tim mengambil keputusan ini dengan baik (minimal 6 langkah).",explain:"Jawaban baik: perjelas keputusan & tenggat + akui trade-off, sajikan fakta netral (semua info sama), kumpulkan opsi termasuk jalan tengah/modifikasi, sepakati kriteria, nilai opsi bersama (menemukan opsi ketiga), putar giliran pendapat + tanya risiko tersembunyi, putuskan lewat konsensus/voting setelah semua didengar, catat keputusan + alasan + rencana penyesuaian, tegaskan dukungan + kekhawatiran tercatat, konsultasi pembimbing bila perlu.",hint:"Perjelas + akui trade-off → fakta netral bersama → opsi (termasuk modifikasi/jalan tengah) → kriteria → nilai bersama → giliran pendapat + tanya risiko → konsensus/voting → catat + rencana penyesuaian → dukungan bersama.",sample:"(1) Perjelas keputusannya & tenggatnya: 'Kita perlu memutuskan hari ini apakah lanjut rencana lama atau ubah, karena tiap hari menunda = lebih banyak waktu terbuang.' Akui ini keputusan besar dengan trade-off nyata. (2) Sajikan fakta bersama secara netral: apa persisnya data yang tidak tersedia, apakah ada sumber alternatif, seberapa lemah hasil bila lanjut, berapa banyak kerja yang terbuang bila ubah, berapa waktu tersisa. Pastikan semua bekerja dari informasi yang sama. (3) Kumpulkan opsi, mungkin lebih dari dua: (a) lanjut rencana lama dengan data seadanya; (b) ubah topik/pendekatan sepenuhnya; (c) modifikasi — pertahankan bagian yang sudah jadi, ganti hanya bagian yang bergantung pada data yang hilang. (4) Sepakati kriteria: kualitas hasil akhir, kelayakan waktu, seberapa banyak kerja lama bisa diselamatkan, beban tambahan untuk tim. (5) Nilai tiap opsi dengan kriteria bersama; sering opsi (c) modifikasi muncul sebagai jalan tengah yang tidak terlihat saat tim hanya berpikir 'lanjut vs ubah total'. (6) Putar giliran: tiap anggota menyampaikan condong & kekhawatiran; aku secara khusus bertanya 'ada risiko yang belum kita bahas?'. (7) Putuskan lewat cara yang disepakati: bila ada opsi yang jelas terbaik setelah penilaian, capai konsensus; bila terbagi, voting setelah semua didengar. (8) Catat keputusan + alasan + rencana penyesuaian tugas & tenggat baru. (9) Tegaskan: 'Kita putuskan ini bareng dengan info yang kita punya sekarang. Yang kalah suara, kekhawatiran kalian tercatat. Ayo kita jalankan bareng.' (10) Bila keputusan besar & tim sangat ragu, aku bisa konsultasi singkat ke guru/pembimbing untuk masukan sebelum final."},
{n:61,type:"mcq",micro:"Mengapa melibatkan tim dalam keputusan besar",q:"Mengapa keputusan besar yang dibuat bersama tim biasanya lebih baik daripada yang dibuat satu orang?",options:["Lebih banyak orang berarti keputusan lebih pintar, tanpa melihat apakah mereka punya informasi atau sudut pandang berbeda; jumlah anggota yang menentukan","Kesalahan bisa dibagi rata kepada anggota bila keputusan keliru, jadi tidak ada satu orang pun yang disalahkan oleh tim","Menggabungkan lebih banyak informasi, sudut pandang, & pengecekan risiko; & anggota lebih memahami serta mendukung keputusan yang ikut mereka buat"],answer:2,explain:"Bukan sekadar 'lebih banyak kepala' — tapi lebih banyak informasi, pengecekan, & komitmen menjalankan.",hint:"Lebih banyak info + pengecekan + komitmen, atau sekadar lebih banyak orang?"},
{n:62,type:"mcq",micro:"Mengapa menyesuaikan cara memutuskan",q:"Mengapa tim sebaiknya memakai cara memutuskan yang berbeda untuk situasi berbeda (konsensus, voting, delegasi, koordinator cepat)?",options:["Tiap cara punya kelebihan (dukungan luas / kecepatan / keahlian / efisiensi) yang cocok untuk jenis & urgensi keputusan yang berbeda","Memakai satu cara terus-menerus terasa membosankan bagi anggota, jadi cara memutuskan perlu diganti-ganti agar lebih seru dan tidak jenuh","Tidak perlu berbeda-beda; satu cara yang sama sudah cukup baik untuk semua keputusan, berapa pun tingkat mendesaknya"],answer:0,explain:"Memaksakan konsensus untuk hal kecil membuang waktu; memaksakan voting cepat untuk hal besar yang butuh keahlian menghasilkan keputusan buruk.",hint:"Tiap cara cocok untuk situasi berbeda, atau satu cukup?"},
{n:63,type:"tf",micro:"Diam bukan persetujuan",q:"Benar atau Salah: Dalam rapat keputusan, diam seorang anggota tidak otomatis berarti ia setuju — bisa jadi ia ragu tapi tidak enak menyampaikannya, atau belum yakin.",answer:true,explain:"Koordinator yang baik secara aktif bertanya 'ada yang belum yakin?' & menyambut kejujuran, bukan menganggap diam = 'ya'.",hint:"Diam = setuju, atau bisa berarti ragu?"},
{n:64,type:"mcq",micro:"Mengapa kriteria membantu",q:"Mengapa menyepakati kriteria SEBELUM menilai opsi membuat keputusan lebih adil?",options:["Tidak membuat keputusan lebih adil; kriteria hanya menambah rumit dan hasilnya sama dengan jika anggota langsung memilih","Kriteria ditetapkan sebelum tim tahu opsi mana yang 'menang', jadi tidak bisa dibuat untuk menguntungkan pilihan favorit seseorang","Kriteria membuat keputusan terlihat lebih pintar di mata guru, bukan untuk mencegah pilihan favorit diuntungkan"],answer:1,explain:"Menetapkan aturan main sebelum tahu siapa untung/rugi (seperti 'satu memotong, satu memilih' kue) membuatnya lebih adil.",hint:"Ditetapkan sebelum tahu pemenangnya, atau sekadar terlihat pintar?"},
{n:65,type:"mcq",micro:"Menilai keputusan yang baik",q:"Keputusan tim yang baik TIDAK diukur dari...",options:["Apakah semua anggota sudah didengar pendapatnya sebelum memutuskan; proses tidak penting dan yang diukur hanyalah hasil akhirnya","Apakah alasan keputusan sudah dicatat dengan jelas; pencatatan tidak ada hubungannya dengan kualitas keputusan yang diambil oleh tim","Apakah hasilnya kebetulan bagus — melainkan dari apakah prosesnya baik (info cukup, semua didengar, kriteria jelas, cara memutuskan tepat)"],answer:2,explain:"Keputusan bagus bisa berhasil karena keberuntungan, & keputusan proses buruk bisa gagal karena nasib. Nilai prosesnya, bukan hanya hasilnya.",hint:"Proses yang baik, atau hasil yang kebetulan bagus?"},
{n:66,type:"tf",micro:"Keputusan bersama selalu lambat?",q:"Benar atau Salah: Melibatkan tim dalam keputusan selalu berarti prosesnya lambat & tidak efisien, jadi keputusan sebaiknya selalu diambil satu orang saja untuk kecepatan.",answer:false,explain:"Sebaliknya, keputusan bersama bisa cepat bila prosesnya terstruktur (kriteria, batas waktu, cara yang disepakati). Dan keputusan yang cepat tapi tidak didukung tim sering lambat dijalankan atau harus diulang.",hint:"Selalu lambat, atau bisa cepat & lebih didukung?"},
{n:67,type:"mcq",micro:"Trade-off dalam keputusan",q:"Hampir setiap keputusan penting melibatkan 'trade-off', yaitu...",options:["Memilih satu hal berarti mengorbankan/melepaskan hal lain — menyadari ini membuat keputusan lebih jujur & realistis","Ada pilihan yang menang di semua hal, jadi tim tidak perlu merelakan sesuatu saat memilih salah satunya","Trade-off hanya ada dalam keputusan bisnis orang dewasa, sedangkan keputusan tim sekolah tak melibatkan pengorbanan"],answer:0,explain:"'Kita pilih yang lebih cepat, tapi menerima kualitasnya sedikit lebih rendah' — menyebut trade-off secara terbuka membuat tim membuat pilihan sadar.",hint:"Memilih satu = melepas lain, atau selalu ada yang menang segalanya?"},
{n:68,type:"mcq",micro:"Keputusan reversibel: pintu satu arah vs dua arah",q:"Membedakan keputusan 'pintu dua arah' (bisa dibalik) & 'pintu satu arah' (sulit dibalik) berguna karena...",options:["Keputusan yang bisa dibalik justru butuh lebih banyak kehati-hatian dibanding yang sulit dibalik, sebab lebih sering terjadi dalam kerja tim sehari-hari","Keputusan yang bisa dibalik bisa diambil cepat & dicoba; yang sulit dibalik layak lebih banyak pertimbangan & kehati-hatian","Semua keputusan sama saja sifatnya & harus diperlakukan dengan proses yang sama, jadi pembedaan itu tidak mengubah cara tim memutuskan"],answer:1,explain:"Menghabiskan waktu berdebat panjang untuk keputusan yang mudah dibalik itu boros. Simpan energi untuk yang permanen.",hint:"Sesuaikan kehati-hatian dengan seberapa sulit dibalik, atau semua sama?"},
{n:69,type:"mcq",micro:"Keputusan & keberagaman tim",q:"Tim yang anggotanya beragam (latar, kemampuan, cara berpikir) dalam mengambil keputusan...",options:["Membuat keputusan lebih buruk; banyaknya perbedaan membuat tim sulit sepakat dan akhirnya mengambil jalan tengah tak berguna","Tidak berbeda dari tim yang seragam; kualitas keputusan hanya ditentukan jumlah anggota, bukan keberagaman mereka","Bisa lebih lambat tapi sering menangkap risiko & peluang yang tim seragam lewatkan — bila perbedaan dikelola dengan hormat"],answer:2,explain:"Keberagaman sudut pandang adalah 'pengecekan' gratis terhadap titik buta, asalkan semua benar-benar didengar.",hint:"Lebih lambat tapi menangkap titik buta, atau selalu lebih buruk?"},
{n:70,type:"order",micro:"Dari keputusan buruk ke pembelajaran",q:"Urutkan langkah tim belajar dari keputusan yang ternyata keliru.",items:["Terima bahwa keputusan itu keliru tanpa saling menyalahkan","Bedakan: apakah prosesnya buruk (info kurang, tidak dengar semua) atau prosesnya oke tapi nasib buruk?","Bila prosesnya yang buruk, identifikasi perbaikan proses untuk lain kali","Fokus sekarang pada memperbaiki situasi & terapkan pelajaran ke keputusan berikutnya"],answer:[0,1,2,3],explain:"Terima → bedakan proses vs nasib → perbaiki proses → perbaiki situasi & terapkan. Menyalahkan orang menghambat pembelajaran.",hint:"Apa yang diterima sebelum menganalisis?"},
{n:71,type:"mcq",micro:"Keputusan & 'kutukan pengetahuan'",q:"Anggota yang paling ahli di suatu bidang kadang membuat keputusan buruk untuk tim karena...",options:["Ia lupa bahwa anggota lain tidak punya konteks yang sama, sehingga keputusannya sulit dipahami & dijalankan tim","Ahli biasanya benar sehingga anggota lain cukup menerima keputusannya tanpa bertanya, dan itu menghemat waktu serta tenaga tim","Keahlian tidak memengaruhi keputusan, karena keputusan tim ditentukan oleh jumlah suara, bukan pengetahuan"],answer:0,explain:"Keputusan yang baik untuk tim harus bisa dipahami & dijalankan tim, bukan hanya optimal 'di atas kertas' bagi si ahli.",hint:"Lupa konteks anggota lain, atau ahli selalu benar?"},
{n:72,type:"tf",micro:"Mengubah keputusan bukan plin-plan",q:"Benar atau Salah: Mengubah keputusan tim ketika muncul informasi baru yang penting adalah tanda kebijaksanaan, bukan tanda plin-plan atau lemah.",answer:true,explain:"Bersikeras pada keputusan yang jelas keliru demi 'terlihat konsisten' merugikan tim. Menyesuaikan berdasarkan fakta baru adalah kekuatan.",hint:"Menyesuaikan dengan fakta baru = bijak, atau plin-plan?"},
{n:73,type:"mcq",micro:"Keputusan & rasa aman untuk menyanggah",q:"Mengapa tim di mana anggota merasa aman menyanggah pilihan koordinator membuat keputusan lebih baik?",options:["Rasa aman tidak memengaruhi kualitas keputusan; hanya data yang menentukan hasilnya","Kelemahan & risiko pilihan itu terungkap sebelum keputusan final, bukan setelah terlambat","Koordinator tidak lagi dihormati dan keputusan diambil lebih cepat oleh anggota"],answer:1,explain:"Koordinator yang hanya didengar 'ya, setuju' kehilangan informasi penting. Menyambut sanggahan adalah tanda pemimpin kuat.",hint:"Risiko terungkap lebih awal, atau koordinator tak dihormati?"},
{n:74,type:"mcq",micro:"Menilai apakah tim butuh mengambil keputusan sama sekali",q:"Sebelum memutuskan, kadang berguna bertanya:",options:["Putuskan segala hal secepat mungkin tanpa menunda; keputusan yang cepat lebih baik daripada yang ditunda, dan itu menandakan tim yang tegas serta efisien","Tunda semua keputusan sampai informasinya lengkap dan sempurna; memutuskan terlalu cepat berakhir dengan kesalahan, dan itu cara paling aman","'Apakah keputusan ini benar-benar perlu diambil sekarang? Bisakah ditunda sampai info lebih lengkap tanpa merugikan? Atau justru menunda merugikan?'"],answer:2,explain:"Kadang menunda dengan sengaja (menunggu info) itu bijak; kadang menunda merugikan. Sadari mana yang berlaku.",hint:"Timbang perlu-sekarang vs bisa-ditunda, atau selalu cepat / selalu tunda?"},
{n:75,type:"tf",micro:"Keputusan bersama & tanggung jawab bersama",q:"Benar atau Salah: Bila keputusan bersama ternyata keliru, yang paling bertanggung jawab adalah anggota yang mengusulkannya, bukan seluruh tim.",answer:false,explain:"Sebaliknya, setelah proses bersama yang adil, seluruh tim ikut bertanggung jawab atas hasilnya. Menyalahkan si pengusul merusak tim & membuat orang takut mengusulkan apa pun.",hint:"Tanggung jawab bersama, atau hanya si pengusul?"},
{n:76,type:"mcq",micro:"Keputusan & informasi yang tidak merata",q:"Bila hanya sebagian anggota punya informasi kunci untuk sebuah keputusan, sebaiknya...",options:["Bagikan informasi itu ke semua sebelum memutuskan, sehingga semua menimbang dari dasar yang sama","Biarkan anggota yang belum tahu ikut voting buta tanpa penjelasan, supaya semua suara dihitung dan terasa adil","Anggota yang punya informasi memutuskan sendiri tanpa menjelaskan, karena dialah yang paham duduk perkaranya"],answer:0,explain:"Keputusan 'bersama' hanya bermakna bila semua punya informasi yang cukup sama untuk ikut menimbang.",hint:"Bagikan info ke semua dulu, atau voting buta / yang tahu memutuskan?"},
{n:77,type:"mcq",micro:"Keputusan & emosi kelompok",q:"Keputusan yang diambil saat tim sedang sangat bersemangat/euforia atau sangat lelah/frustrasi cenderung...",options:["Tidak dipengaruhi suasana hati; keputusan baik hanya ditentukan data, bukan perasaan yang dialami anggota tim, dan waktu rapat tak memengaruhi apa-apa","Kurang seimbang — euforia mengabaikan risiko, kelelahan mengabaikan peluang; keputusan besar lebih baik diambil saat tim tenang & fokus","Lebih baik jujur dan spontan sesuai perasaan saat itu, jadi sebaiknya diputuskan ketika emosi anggota sedang kuat; keputusan terasa tulus"],answer:1,explain:"Suasana hati kelompok memengaruhi penilaian. Untuk keputusan besar, pilih waktu ketika tim bisa berpikir jernih.",hint:"Kurang seimbang (euforia/lelah), atau tak dipengaruhi suasana?"},
{n:78,type:"mcq",micro:"Konsensus semu vs konsensus sejati",q:"Beda 'semua diam jadi dianggap setuju' & konsensus sejati:",options:["Keduanya sama; sama-sama berarti tim tidak berdebat lagi dan keputusan siap dijalankan, serta sama-sama menghemat waktu diskusi bagi seluruh anggota","Konsensus semu lebih baik; lebih cepat dicapai, dan koordinator tak perlu repot menanyakan keraguan tiap anggota satu per satu di rapat","Konsensus sejati: koordinator aktif menanyakan keraguan, tiap orang secara sadar menyatakan bisa mendukung. Konsensus semu: diam ditafsirkan sebagai setuju"],answer:2,explain:"Konsensus semu menyembunyikan keraguan yang bisa menyelamatkan tim. Selalu tanyakan 'ada yang belum yakin?'.",hint:"Menanyakan keraguan aktif vs menafsirkan diam, atau sama?"},
{n:79,type:"mcq",micro:"Keputusan & keadilan yang dirasakan",q:"Anggota lebih menerima keputusan yang bukan pilihannya bila...",options:["Ia merasa pendapatnya benar-benar didengar & dipertimbangkan, prosesnya transparan & konsisten, & alasan keputusannya dijelaskan","Ia dipaksa menurut oleh suara mayoritas tanpa penjelasan; alasan keputusan dianggap tak perlu diketahui anggota yang kalah","Keputusan dibuat diam-diam oleh sebagian anggota lalu diumumkan sebagai hasil final, dan tak ada kesempatan bertanya"],answer:0,explain:"'Keadilan prosedural': orang menerima hasil yang tidak menyenangkan bila prosesnya dianggap adil.",hint:"Didengar + transparan + dijelaskan, atau dipaksa / diam-diam?"},
{n:80,type:"open",micro:"Membandingkan dua tim",q:"Tim A memutuskan dengan: ketua mengusulkan, tanya 'setuju?', semua diam, langsung jalan — cepat tapi sering keputusannya berlubang & anggota menjalankan setengah hati. Tim B memutuskan dengan: perjelas keputusan, kumpulkan opsi, sepakati kriteria, semua sebut pendapat & kekhawatiran bergiliran, putuskan lewat cara yang disepakati, catat alasan — lebih lambat tapi keputusannya matang & dijalankan sepenuh hati. Jelaskan mengapa cara Tim B lebih baik untuk hasil jangka panjang (minimal 4 alasan), dan 1 situasi di mana kecepatan Tim A justru lebih tepat.",explain:"Jawaban baik memberi minimal 4 alasan Tim B lebih baik jangka panjang (keputusan lebih matang / lubang ketahuan, anggota menjalankan sepenuh hati, risiko dibicarakan & disiapkan, catatan alasan mencegah pembongkaran ulang, tim belajar & membaik) dan 1 situasi kecepatan Tim A tepat (keputusan kecil / rutin / mudah dibalik, atau mendesak yang tak bisa menunggu — dijelaskan setelahnya).",hint:"Alasan B: matang & lubang ketahuan, dijalankan sepenuh hati, risiko disiapkan, catatan alasan, tim membaik. Kecepatan A tepat untuk: keputusan kecil/rutin/mudah dibalik atau mendesak.",sample:"Cara Tim B lebih baik untuk jangka panjang karena: (1) Keputusannya lebih matang — beberapa opsi dipertimbangkan dan dinilai dengan kriteria, sehingga lubang seperti yang dialami Tim A (data tidak tersedia, dll.) lebih mungkin ketahuan sebelum mulai. (2) Semua anggota mendengar alasan dan merasa didengar, jadi mereka menjalankan keputusan sepenuh hati, bukan setengah hati seperti di Tim A — dan pelaksanaan yang sepenuh hati sering lebih menentukan hasil daripada pilihan itu sendiri. (3) Keraguan dan risiko yang di Tim A disembunyikan (semua diam padahal ragu) di Tim B dibicarakan, sehingga tim bisa menyiapkan rencana menghadapinya. (4) Catatan alasan membuat tim tidak membongkar ulang keputusan tiap kali ada keraguan, dan bisa menjelaskannya ke pihak luar. (5) Tim B belajar cara memutuskan yang baik, sehingga keputusan berikutnya makin efektif; Tim A akan terus membuat keputusan berlubang. Situasi di mana kecepatan Tim A lebih tepat: untuk keputusan kecil, rutin, dan mudah dibalik (misalnya 'pakai warna biru atau hijau untuk judul poster', 'rapat jam 4 atau 4.30') — di sini proses panjang Tim B hanya membuang waktu, dan bila salah pun mudah diperbaiki. Kecepatan juga tepat untuk keputusan mendesak yang benar-benar tidak bisa menunggu, asalkan dijelaskan ke tim setelahnya."},
{n:81,type:"mcq",micro:"Kasus: keputusan menyangkut nilai & etika",q:"Tim harus memutuskan sesuatu di mana opsi tercepat sedikit tidak jujur (mis. mengarang sebagian data agar hasil terlihat bagus). Sikap:",options:["Serahkan keputusannya ke koordinator dan ikuti pilihannya; tanggung jawab etika sepenuhnya ada padanya sebagai pemimpin","Keputusan tim tidak boleh melanggar kejujuran/etika, betapapun menguntungkan; pilih opsi yang jujur meski lebih lambat/kurang menonjol","Ikuti suara terbanyak meski yang dipilih opsi tidak jujur; keputusan bersama otomatis sah dan tidak perlu dipertanyakan"],answer:1,explain:"Ada keputusan yang batasnya bukan 'apa yang tim mau' tapi 'apa yang benar'. Kejujuran & etika tidak untuk divoting.",hint:"Pilih yang jujur meski lambat, atau ikut suara terbanyak / serahkan?"},
{n:82,type:"mcq",micro:"Kasus: keputusan & anggota yang selalu jadi minoritas",q:"Seorang anggota hampir selalu kalah suara di tiap keputusan & mulai merasa suaranya percuma. Sikap tim:",options:["Biarkan saja, dia memang sering kalah suara dan itulah risiko keputusan bersama yang harus diterima setiap anggota dengan lapang dada, dan hal itu tidak perlu dibahas bersama anggota lain","Suruh dia berhenti punya pendapat yang berbeda dari mayoritas; ia tidak perlu terus merasa kalah dan keputusan tim bisa diambil lebih cepat lagi, dan tim lebih kompak","Pastikan pendapatnya benar-benar ditimbang tiap kali (bukan formalitas); bila kekhawatirannya beralasan, sesekali akomodasi; & jelaskan alasan keputusan yang berbeda darinya"],answer:2,explain:"Selalu kalah suara berbeda dari tidak didengar. Tim yang sehat menjaga anggota minoritas tetap merasa berarti.",hint:"Tetap ditimbang serius + sesekali akomodasi + jelaskan alasan, atau biarkan / suruh diam?"},
{n:83,type:"tf",micro:"Refleksi: keputusan bersama = keterampilan tim inti",q:"Benar atau Salah: Kemampuan sebuah tim untuk mengambil keputusan bersama yang matang, adil, & didukung semua anggota adalah salah satu keterampilan paling menentukan bagi keberhasilan tim.",answer:true,explain:"Tim bisa punya anggota berbakat & sumber daya cukup, tapi tetap gagal bila tidak bisa memutuskan bersama dengan baik.",hint:"Menentukan keberhasilan tim, atau tidak penting?"},
{n:84,type:"mcq",micro:"Kasus: koordinator memaksakan keputusannya lewat 'proses palsu'",q:"Koordinator menjalankan 'diskusi' tapi jelas sudah memutuskan & hanya mencari pembenaran. Sikap anggota:",options:["Sampaikan dengan tenang: 'Kalau keputusannya sudah dibuat, nggak apa-apa, tapi tolong sampaikan langsung. Kalau ini benar-benar dibahas, aku pengin pendapatku ditimbang beneran.'","Ikut pura-pura berdiskusi dan mengangguk sepanjang rapat agar suasana tetap baik dan tak ada yang merasa canggung atau terganggu, lalu menerima apa yang diumumkan nanti","Menyabotase keputusan itu diam-diam sebagai balasan karena merasa dipermainkan, dan tunjukkan bahwa diskusi tidak boleh hanya formalitas belaka"],answer:0,explain:"Menamai 'proses palsu' dengan sopan mendorong keterbukaan: sebut langsung bila sudah diputuskan, atau benar-benar buka diskusi.",hint:"Namai dengan sopan + minta kejelasan, atau ikut pura-pura / sabotase?"},
{n:85,type:"order",micro:"Mengambil keputusan besar yang sulit dibalik",q:"Urutkan langkah tim mengambil keputusan besar & sulit dibalik dengan hati-hati.",items:["Perjelas keputusan, batas waktu, & akui bahwa ini sulit dibalik","Kumpulkan beberapa opsi + informasi lengkap; pastikan semua punya info yang sama","Sepakati kriteria; nilai tiap opsi; sengaja cari kelemahan & risiko tiap opsi","Dengar semua pendapat & keraguan; putuskan lewat konsensus/voting; catat keputusan + alasan + rencana bila keliru"],answer:[0,1,2,3],explain:"Perjelas + akui besarnya → opsi & info merata → kriteria + cari kelemahan → dengar semua + putuskan + catat + rencana cadangan.",hint:"Apa yang diakui di awal untuk keputusan yang sulit dibalik?"},
{n:86,type:"mcq",micro:"Kasus: keputusan & tekanan waktu yang dibuat-buat",q:"Seseorang mendesak keputusan cepat 'harus sekarang!' padahal sebenarnya masih ada waktu. Sikap:",options:["Abaikan orang itu sepenuhnya dan lanjutkan proses seperti biasa, tanpa memeriksa apakah batas waktu yang ia sebutkan memang benar-benar ada atau tidak","Cek: apakah benar mendesak? Bila tidak, minta waktu yang wajar untuk mempertimbangkan — tekanan waktu buatan sering menghasilkan keputusan buruk","Ikuti desakan waktu dari siapa saja dan putuskan sekarang juga; menunda keputusan dianggap lebih berbahaya daripada salah memilih"],answer:1,explain:"Tekanan waktu palsu adalah cara umum mendorong keputusan tanpa pemikiran cukup. Verifikasi urgensinya.",hint:"Cek urgensi sebenarnya, atau selalu ikuti desakan / abaikan?"},
{n:87,type:"tf",micro:"Keputusan bersama tidak berarti tanpa pemimpin",q:"Benar atau Salah: Keputusan bersama yang baik terjadi dengan sendirinya tanpa perlu ada yang memandu proses; menunjuk fasilitator justru membuatnya kurang 'bersama'.",answer:false,explain:"Sebaliknya, keputusan bersama yang baik butuh seseorang yang memandu proses (menjaga fokus, memastikan semua didengar, membawa ke keputusan). Tanpa itu, diskusi berputar-putar & yang terkeras menang.",hint:"Tetap butuh fasilitator, atau bersama = tanpa arah?"},
{n:88,type:"mcq",micro:"Kasus: keputusan yang membelah tim jadi kubu",q:"Sebuah keputusan sudah membelah tim jadi dua kubu yang saling dingin. Cara memutuskan yang bisa memulihkan:",options:["Kubu mayoritas memaksakan pilihannya karena jumlah suara lebih banyak, lalu kubu minoritas diminta menyesuaikan diri tanpa banyak bertanya agar tim cepat kembali bekerja, dan keputusan dicatat sebagai hasil resmi","Tunda forum itu sampai kedua kubu sendiri-sendiri menemukan solusinya, tanpa dibahas bersama; tidak ada tekanan untuk memutuskan dalam waktu dekat ini, lalu lanjut bekerja terpisah","Forum terbuka dengan aturan hormat: tiap kubu menjelaskan kebutuhan & kekhawatirannya, cari opsi yang mengakomodasi keduanya sebagian, putuskan lewat cara disepakati, & tegaskan komitmen tetap satu tim setelahnya"],answer:2,explain:"Keputusan yang membelah tim butuh proses yang sengaja menyembuhkan: dengar kebutuhan tiap kubu, cari akomodasi, & pulihkan hubungan.",hint:"Forum terbuka + akomodasi + pulihkan hubungan, atau mayoritas memaksa / tunda?"},
{n:89,type:"mcq",micro:"Kasus: keputusan & hasil buruk padahal proses baik",q:"Tim mengambil keputusan lewat proses yang sangat baik (info cukup, semua didengar, kriteria jelas), tapi hasilnya tetap buruk karena kejadian tak terduga. Sikap saat refleksi:",options:["Akui bahwa keputusan itu masuk akal dengan info yang ada saat itu; jangan menghukum diri/tim atas nasib buruk; periksa apakah ada info yang seharusnya bisa didapat","'Kita bodoh, seharusnya sudah tahu dari awal!' lalu saling menyalahkan di dalam tim, dan anggap semua anggota akan lebih berhati-hati pada keputusan berikutnya","Berhenti mengambil keputusan penting secara bersama mulai sekarang dan menyerahkannya kepada satu orang saja; proses kelompok terbukti tidak menjamin hasil"],answer:0,explain:"Keputusan bagus bisa berujung buruk karena nasib. Menghukum tim atas hasil (bukan proses) membuat orang takut memutuskan.",hint:"Akui keputusan masuk akal saat itu + cek info yang bisa didapat, atau saling menyalahkan?"},
{n:90,type:"open",micro:"Kasus menyeluruh",q:"Kamu ketua tim OSIS 10 orang untuk setahun. Kamu ingin membangun tim yang bisa mengambil keputusan bersama dengan baik: matang, adil, cepat saat perlu, dan didukung semua — bahkan saat ada perbedaan pendapat tajam & tekanan waktu. Rancang bagaimana kamu membangun kemampuan ini. Minimal 6 praktik konkret dengan alasan.",explain:"Jawaban baik memuat minimal 6 praktik konkret dengan alasan: mekanisme keputusan tertulis (klasifikasi + cara), perjelas keputusan & besarnya tiap kali, kumpulkan beberapa opsi + sepakati kriteria dulu, libatkan yang pendiam (giliran/tulis) + tanya keraguan aktif (anti-groupthink), batas waktu + cara memutuskan bila buntu, catat keputusan + alasan + kapan dievaluasi, 'tidak setuju tetap komit' + akomodasi minoritas beralasan, memodelkan menerima sanggahan, refleksi berkala.",hint:"Bangun kemampuan: mekanisme tertulis, perjelas tiap keputusan, opsi + kriteria dulu, libatkan pendiam + tanya keraguan, batas waktu + cara bila buntu, catat + evaluasi, komit setelah adil + akomodasi minoritas, model menerima sanggahan, refleksi.",sample:"(1) Di awal kepengurusan, tim menyepakati MEKANISME keputusan tertulis: keputusan besar lewat rapat + kriteria + konsensus (voting bila buntu); keputusan menengah oleh PJ bidang; kecil-mendesak oleh ketua lalu dijelaskan. Alasan: menyepakati cara memutuskan saat tenang mencegah konflik soal 'caranya' saat ada keputusan sulit. (2) Untuk tiap keputusan besar, aku mulai dengan memperjelas: keputusan apa, batasnya kapan, seberapa sulit dibalik. Alasan: proses menyesuaikan besarnya keputusan. (3) Aku selalu meminta beberapa opsi dikumpulkan dulu (bukan hanya satu usulan), dan tim menyepakati kriteria penilaian sebelum menilai. Alasan: mencegah keputusan 'satu opsi saja' dan membuat penilaian objektif & adil. (4) Dalam diskusi, aku memakai giliran atau minta menulis pendapat dulu supaya anggota pendiam ikut, dan aku secara khusus bertanya 'siapa yang punya keraguan atau melihat risiko?' — dan menyambut jawabannya, bukan mengabaikannya. Alasan: melawan groupthink & ilusi konsensus. (5) Aku menetapkan batas waktu diskusi yang wajar dan cara memutuskan bila buntu (voting setelah semua didengar), supaya menghargai perbedaan tidak jadi kebuntuan. Alasan: tim tetap harus bergerak. (6) Setiap keputusan penting dicatat: apa, kenapa, siapa mengerjakan apa, kapan dievaluasi. Alasan: acuan & mencegah pembongkaran ulang. (7) Setelah keputusan lewat proses adil, aku menegaskan 'tidak setuju tetap komit' dan memastikan yang kalah suara kekhawatirannya tercatat & sebagian diakomodasi bila beralasan. (8) Aku memodelkan sikap menerima sanggahan: ketika anggota menyanggah usulku dengan alasan, aku berterima kasih, bukan tersinggung. Alasan: tim meniru pemimpin; kalau menyanggah aman, informasi mengalir. (9) Berkala (mis. tiap 2 bulan) tim merefleksikan: keputusan mana yang berjalan baik? cara kita memutuskan sudah adil & efisien? apa yang perlu diubah?"},
{n:91,type:"mcq",micro:"Kasus: keputusan & anggota yang menolak semua opsi",q:"Seorang anggota menolak setiap opsi tanpa menawarkan alternatif & tanpa alasan yang bisa ditindaklanjuti. Sikap tim:",options:["Terus mencari opsi baru tanpa akhir sampai anggota itu merasa puas, walaupun tenggat sudah dekat dan tim kehabisan waktu serta tenaga untuk memutuskan, lalu berharap masalahnya selesai sendiri","Minta ia mengajukan alternatif konkret atau menjelaskan kriteria apa yang harus dipenuhi; bila tetap hanya menolak, tim tetap memutuskan lewat mekanisme yang disepakati — satu orang tidak bisa menyandera keputusan","Menuruti penolakannya dan membatalkan setiap opsi yang ia tolak; ia tidak boleh merasa tersisih dan suasana tim tetap tenang serta kompak, walaupun keputusan jadi sulit selesai, dan tenggat terlewati"],answer:1,explain:"Menghormati berarti mendengar & memberi ruang mengusulkan; tapi menolak tanpa alternatif tidak bisa melumpuhkan tim selamanya.",hint:"Minta alternatif konkret lalu tetap putuskan lewat mekanisme, atau selalu turuti / cari tanpa akhir?"},
{n:92,type:"tf",micro:"Refleksi: keputusan melayani tujuan & orang",q:"Benar atau Salah: Keputusan tim yang baik menghasilkan dua hal: pilihan yang matang & tepat untuk tujuan, DAN anggota tim yang merasa didengar serta bersedia mendukung & menjalankan keputusan itu.",answer:true,explain:"Keputusan 'benar di atas kertas' yang tidak didukung tim sering gagal saat dijalankan. Keputusan yang didukung tapi asal-asalan juga gagal. Butuh keduanya.",hint:"Pilihan matang + tim mendukung, atau salah satu?"},
{n:93,type:"mcq",micro:"Kasus: keputusan lintas tim/organisasi",q:"Keputusan timmu akan memengaruhi beberapa bidang OSIS lain. Cara memutuskan yang tepat:",options:["Putuskan sendiri saja karena 'ini keputusan bidang kami', dan bidang lain tinggal menyesuaikan diri begitu keputusannya diumumkan nantinya, lalu mengira masalahnya selesai di tim","Tidak memutuskan apa-apa agar bidang lain tidak merasa terganggu, walaupun tim perlu menentukan langkah kerjanya segera, lalu menunggu mereka bersuara lebih dulu, sambil berharap segalanya membaik","Libatkan perwakilan bidang yang terdampak dalam pembahasan sebelum memutuskan, atau setidaknya konsultasikan; keputusan yang mengejutkan pihak lain sering ditolak & memicu konflik antar bidang"],answer:2,explain:"Keputusan yang berdampak lintas tim butuh koordinasi. Melibatkan pihak terdampak lebih dulu jauh lebih lancar daripada memutuskan sepihak.",hint:"Libatkan/konsultasikan pihak terdampak, atau sepihak / tidak memutuskan?"},
{n:94,type:"mcq",micro:"Kasus: refleksi soal keputusan tim",q:"Cara tim melatih kemampuan mengambil keputusan lewat refleksi:",options:["Setelah keputusan penting berjalan sebentar: apakah prosesnya adil & cukup matang? apakah semua merasa didengar? apa yang berjalan baik / perlu diubah untuk keputusan berikutnya?","Menyimpulkan bahwa keputusan buruk berarti ada orang tertentu yang bersalah, lalu menegurnya di depan tim untuk mencegah kesalahan di keputusan berikutnya","Tidak mengevaluasi keputusan yang sudah berjalan; yang sudah diputuskan tidak perlu dibahas lagi dan lebih baik fokus ke pekerjaan berikutnya, sampai ada masalah besar"],answer:0,explain:"Meninjau PROSES keputusan (bukan hanya hasilnya, & bukan mencari kambing hitam) membuat tim makin efektif memutuskan.",hint:"Evaluasi proses & keterlibatan, atau cari yang salah / tak pernah?"},
{n:95,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti mengambil keputusan bersama:",options:["Gunakan voting cepat untuk semua hal, besar maupun kecil, tanpa membahas opsi, kriteria, atau risiko, dan selesaikan dalam hitungan menit, tanpa menjelaskan alasannya kepada anggota, jadi anggota harus menebak-nebak","Perjelas keputusan; kumpulkan opsi & info; sepakati kriteria; dengar semua pendapat & keraguan; pilih cara memutuskan yang tepat (konsensus/voting/delegasi); catat keputusan + alasan; dukung hasil proses adil; tinjau bila ada info baru","Ketua memutuskan sendiri segala hal lalu mengumumkannya tanpa meminta pendapat; itu dianggap cepat dan jelas, dan anggota tinggal menjalankan arahan tanpa tahu apa yang sebenarnya terjadi"],answer:1,explain:"Ringkasan: perjelas + opsi & info merata + kriteria + dengar semua + cara yang tepat + catat + dukung + tinjau.",hint:"Perjelas, opsi & info merata, kriteria, dengar semua, cara tepat, catat, dukung, tinjau — rangkai."},
{n:96,type:"tf",micro:"Refleksi: proses lebih penting daripada satu keputusan",q:"Benar atau Salah: Yang paling penting bagi seorang anggota tim adalah memastikan pilihannya sendiri menang di setiap keputusan; memperbaiki cara tim mengambil keputusan hanya urusan sekunder.",answer:false,explain:"Sebaliknya, membangun proses keputusan yang baik (adil, matang, sesuai situasi) lebih penting jangka panjang daripada 'menang' satu keputusan, karena proses yang baik menghasilkan ratusan keputusan yang lebih baik.",hint:"Proses yang baik (banyak keputusan), atau menang satu keputusan?"},
{n:97,type:"mcq",micro:"Kasus: memulai memperbaiki cara timmu memutuskan",q:"Cara termudah mulai memperbaiki pengambilan keputusan di kelompok berikutnya:",options:["Menunggu sampai tim kita lebih terorganisasi & punya ketua yang tegas, baru kemudian mulai mencoba cara mengambil keputusan yang lebih terstruktur dengan mereka nanti","Membiarkan keputusan terjadi seperti biasa tanpa mengubah cara, karena kebiasaan lama kelompok sudah cukup baik dan tak perlu diganggu usul baru, sampai ada masalah","Di keputusan penting berikutnya, usulkan tiga hal: kumpulkan lebih dari satu opsi, sepakati kriteria sebelum menilai, & putar giliran agar semua sebut pendapat sebelum memutuskan"],answer:2,explain:"Tiga kebiasaan kecil (beberapa opsi, kriteria dulu, giliran pendapat) sudah sangat meningkatkan kualitas & keadilan keputusan tim.",hint:"Usulkan opsi + kriteria + giliran, atau menunggu / membiarkan?"},
{n:98,type:"tf",micro:"Refleksi: keputusan bersama menguatkan tim",q:"Benar atau Salah: Tim yang terbiasa mengambil keputusan bersama dengan adil & matang cenderung lebih saling percaya, lebih kompak menjalankan rencana, & lebih tahan menghadapi kesulitan.",answer:true,explain:"Setiap keputusan bersama yang baik adalah latihan kepercayaan & kerja sama. Ia menguatkan tim untuk keputusan & tantangan berikutnya.",hint:"Menguatkan tim, atau tak berpengaruh?"},
{n:99,type:"mcq",micro:"Kasus: keputusan & keberanian memutuskan",q:"Setelah semua opsi ditimbang & semua didengar, tim masih ragu & terus menunda. Sikap yang dibutuhkan:",options:["Keberanian untuk memutuskan: 'Kita sudah timbang cukup. Nggak ada opsi sempurna. Ayo kita pilih [X] karena [alasan], jalankan, & evaluasi di [waktu].'","Terus menunggu sampai semua anggota yakin 100% pada satu pilihan, karena keputusan yang masih menyisakan keraguan sebaiknya tidak dijalankan","Menyerahkan keputusan pada undian tanpa pertimbangan, supaya tak seorang pun disalahkan dan tim tak perlu membahas pilihan lagi, lalu lanjut"],answer:0,explain:"Ada titik di mana pertimbangan lebih lanjut tidak menambah kejelasan & yang dibutuhkan adalah keputusan. Memutuskan + rencana evaluasi lebih baik daripada lumpuh.",hint:"Berani memutuskan + rencana evaluasi, atau menunggu 100% yakin / undian?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi keputusan bersama",q:"Tulis 'aturan pribadi tentang mengambil keputusan bersama dalam tim' berisi minimal 5 poin yang akan kamu pegang, masing-masing dengan alasan singkat.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide inti bab: beberapa opsi + kriteria sebelum menilai, sampaikan pendapat beralasan + terbuka pada sanggahan, libatkan yang pendiam + diam bukan setuju, dukung keputusan proses adil ('tidak setuju tetap komit'), pilih cara memutuskan sesuai situasi, catat keputusan + alasan, tinjau bila ada info baru, nilai proses bukan hanya hasil.",hint:"Ambil satu pelajaran tiap fase — opsi + kriteria, pendapat beralasan + terbuka, libatkan pendiam, komit setelah adil, cara sesuai situasi, catat alasan, tinjau bila info baru, nilai proses — jadikan aturan 'aku akan...'.",sample:"Contoh aturan pribadi: (1) Untuk keputusan penting, aku ikut memastikan tim mengumpulkan lebih dari satu opsi & menyepakati kriteria sebelum menilai — karena satu opsi tanpa kriteria menghasilkan keputusan yang tidak teruji & tidak adil. (2) Aku menyampaikan pendapatku dengan alasan & tetap terbuka mendengar sanggahan — bukan memaksa atau menahan pendapat kuat. (3) Aku memperhatikan anggota yang pendiam & mendorong mereka bicara (atau menulis pendapat dulu), dan aku tidak menganggap diam berarti setuju — karena keputusan bersama harus mencerminkan semua, bukan yang paling vokal. (4) Setelah tim memutuskan lewat proses yang adil, aku mendukung & menjalankan keputusan itu meski bukan pilihanku, sambil boleh mencatat kekhawatiranku — karena menghormati proses berarti menerima hasilnya. (5) Aku membantu tim memilih CARA memutuskan yang sesuai situasi (konsensus untuk yang besar, voting bila buntu & waktu terbatas, delegasi untuk yang teknis, koordinator cepat untuk yang kecil/mendesak) — karena satu cara tidak cocok untuk semua. (6) Aku mendorong tim mencatat keputusan + alasannya — supaya jadi acuan & tidak dibongkar ulang tiap ada keraguan. (7) Bila muncul informasi baru yang penting, aku mengusulkan tim meninjau keputusan — karena menyesuaikan dengan fakta baru itu bijak, bukan plin-plan. (8) Aku menilai keputusan dari kualitas prosesnya, bukan hanya dari hasil yang kebetulan bagus/buruk."},
];
